from collections import defaultdict

def find_components_and_boxes(grid, color):
    H, W = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == color and (r, c) not in visited:
                comp = []
                stack = [(r, c)]
                visited.add((r, c))
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))
                components.append(comp)

    boxes = []
    for comp in components:
        rs = [cr for cr, cc in comp]
        cs = [cc for cr, cc in comp]
        boxes.append({
            'count': len(comp),
            'box': (min(rs), max(rs), min(cs), max(cs))
        })

    return boxes

